// Provider request from the route config (ai_prepare), the prompt template and the caller's vars / files.
const input = $('Input').first().json;
const p = $('Prepare').first().json.p;
const params = p.params || {};
const files = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  if (items[i].binary && items[i].binary.data) {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    files.push({ kind: items[i].json.kind, mime: items[i].json.mime || items[i].binary.data.mimeType, b64: buf.toString('base64') });
  }
}

// Structured outputs accept a JSON Schema subset: drop validation-only keywords, inline $refs, close every object.
function strict(schema) {
  const defs = schema.$defs || schema.definitions || {};
  const drop = new Set(['$schema', '$id', '$defs', 'definitions', 'minLength', 'maxLength', 'minimum', 'maximum', 'exclusiveMinimum',
    'exclusiveMaximum', 'multipleOf', 'minItems', 'maxItems', 'uniqueItems', 'pattern', 'format', 'default', 'examples', 'title']);
  const walk = (s) => {
    if (Array.isArray(s)) return s.map(walk);
    if (!s || typeof s !== 'object') return s;
    if (s.$ref) return walk(defs[s.$ref.split('/').pop()] || {});
    const out = {};
    for (const [k, v] of Object.entries(s)) {
      if (drop.has(k)) continue;
      out[k] = k === 'properties' ? Object.fromEntries(Object.entries(v).map(([pk, pv]) => [pk, walk(pv)])) : walk(v);
    }
    if (out.properties) {
      out.additionalProperties = false;
      out.required = Object.keys(out.properties);
    }
    return out;
  };
  return walk(schema);
}

// Prompt template: <<<system>>> (stable rules), <<<cache>>> (stable brand block, cached), <<<user>>> (volatile). {{var}} / {{a.b}} from vars.
function render(t) {
  return t.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, k) => {
    const v = k.split('.').reduce((o, x) => (o == null ? undefined : o[x]), input.vars || {});
    return v == null ? '' : typeof v === 'string' ? v : JSON.stringify(v, null, 1);
  });
}

let url, body, headers = {};
if (p.provider === 'anthropic') {
  const sec = { system: '', cache: '', user: '' };
  let cur = 'user';
  for (const line of String(p.template || '').split('\n')) {
    const m = line.match(/^<<<(system|cache|user)>>>\s*$/);
    if (m) { cur = m[1]; continue; }
    sec[cur] += line + '\n';
  }
  const system = [];
  if (sec.system.trim()) system.push({ type: 'text', text: render(sec.system).trim() });
  if (sec.cache.trim()) system.push({ type: 'text', text: render(sec.cache).trim(), cache_control: { type: 'ephemeral' } });
  const content = files.map((f) => f.mime === 'application/pdf'
    ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: f.b64 } }
    : { type: 'image', source: { type: 'base64', media_type: f.mime, data: f.b64 } });
  content.push({ type: 'text', text: render(sec.user).trim() || 'Go.' });
  body = { model: p.model, max_tokens: params.max_tokens || 8000, messages: [{ role: 'user', content }], fallbacks: 'default' };
  if (system.length) body.system = system;
  const oc = {};
  if (params.effort) oc.effort = params.effort;
  if (p.schema) oc.format = { type: 'json_schema', schema: strict(p.schema) };
  if (Object.keys(oc).length) body.output_config = oc;
  url = p.base_url + '/v1/messages';
  headers = { 'anthropic-version': '2023-06-01', 'anthropic-beta': 'server-side-fallback-2026-07-01' };
} else if (p.kind === 'stt') {
  const f = files[0];
  if (!f) throw new Error('fatal: no audio file for speech-to-text');
  const ext = { 'audio/ogg': 'ogg', 'audio/opus': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp3': 'mp3', 'audio/mp4': 'm4a', 'audio/x-m4a': 'm4a',
                'audio/m4a': 'm4a', 'audio/wav': 'wav', 'audio/x-wav': 'wav', 'audio/flac': 'flac', 'audio/aac': 'aac', 'audio/webm': 'webm' }[f.mime] || 'ogg';
  url = p.base_url + '/audio/transcriptions';
  body = { model: p.model, input_audio: { data: f.b64, format: ext } };
} else if (p.kind === 'image') {
  url = p.base_url + '/images';
  body = { model: p.model, prompt: String(input.prompt || '').slice(0, 4000), aspect_ratio: input.aspect_ratio || '16:9', ...params };
} else {
  url = p.base_url + '/embeddings';
  const clip = (t) => String(t ?? '').slice(0, 30000);
  body = { model: p.model, input: Array.isArray(input.input) ? input.input.map(clip) : clip(input.input), dimensions: params.dimensions || 1536 };
}
return [{ json: { provider: p.provider, url, body, headers, started: Date.now() } }];

// Classify the provider answer: ok / retryable (provider_unavailable) / permanent (fatal), usage for ai_record.
const req = $('Build request').first().json;
const input = $('Input').first().json;
const p = $('Prepare').first().json.p;
const r = $json;
const code = r.statusCode || 0;
const b = r.body;
const msg = () => (b && typeof b === 'object' ? (b.error?.message || b.message || JSON.stringify(b).slice(0, 300)) : String(b || '').slice(0, 300));
const rec = { route: input.route, provider: p.provider, model: p.model, prompt_hash: p.prompt_hash, account_type: input.account_type || 'system',
  brand_id: input.brand_id ?? null, material_id: input.material_id ?? null, package_id: input.package_id ?? null,
  variant_id: input.variant_id ?? null, job_id: input.job_id ?? null, latency_ms: Date.now() - req.started, status: 'error' };
let ok = false, result = null, err = null;
if (r.error || !code) err = 'provider_unavailable: ' + String(r.error?.message || r.error || 'no response').slice(0, 300);
else if (code === 429 || code >= 500) err = `provider_unavailable: HTTP ${code} ${msg()}`;
else if (code === 401 || code === 403) err = `fatal: HTTP ${code} — check the ${p.provider} API key in n8n credentials`;
else if (code >= 400) err = `fatal: HTTP ${code} ${msg()}`;
else if (p.provider === 'anthropic') {
  const u = b.usage || {};
  Object.assign(rec, { input_tokens: u.input_tokens || 0, output_tokens: u.output_tokens || 0, cache_write_tokens: u.cache_creation_input_tokens || 0,
                       cache_read_tokens: u.cache_read_input_tokens || 0, stop_reason: b.stop_reason, model: b.model || p.model });
  const text = (b.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('');
  if (b.stop_reason === 'refusal') { rec.status = 'refused'; err = 'fatal: the model declined this request'; }
  else if (b.stop_reason === 'max_tokens') { rec.status = 'invalid'; err = 'fatal: the answer was cut at max_tokens'; }
  else if (p.schema) {
    try { result = JSON.parse(text); ok = true; } catch (e) { rec.status = 'invalid'; err = 'invalid JSON from the model: ' + e.message; }
  } else { result = text; ok = text.trim() !== ''; if (!ok) { rec.status = 'invalid'; err = 'empty answer from the model'; } }
} else {
  rec.cost_usd = b?.usage?.cost ?? null;
  if (p.kind === 'stt') { result = typeof b.text === 'string' ? b.text : null; rec.units = { seconds: b?.usage?.seconds ?? null }; }
  else if (p.kind === 'image') {
    const d = (b.data || [])[0] || {};
    let b64 = d.b64_json || null;
    if (!b64 && typeof d.url === 'string' && d.url.startsWith('data:')) b64 = d.url.split(',')[1];
    result = b64 ? { image_b64: b64, mime: (d.url || '').match(/^data:([^;]+)/)?.[1] || 'image/png' } : null;
    rec.units = { images: 1 };
  } else {  // embeddings: one vector for a string input, a list (in input order) for an array input
    const vecs = (b.data || []).slice().sort((x, y) => (x.index ?? 0) - (y.index ?? 0)).map((x) => x.embedding);
    result = Array.isArray(input.input) ? (vecs.length === input.input.length ? vecs : null) : (vecs[0] || null);
  }
  ok = result != null;
  if (!ok) { rec.status = 'invalid'; err = `invalid response from ${p.provider} (${p.kind})`; }
}
if (ok) rec.status = 'ok';
rec.error = err;
return { json: { ok, result, error: err, record: rec } };
